697	    include: { subscription: true },
698	  });
699	  if (!mailbox) return { error: "Mailbox not found." };
700	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
701	
702	  // Best-effort delete on Mailcow before dropping the row — a mail-server outage
703	  // must not block the customer from removing the mailbox record.
704	  if (mailcowConfigured()) {
