112	export async function ensurePhpFpm(conn: import("ssh2").Client, phpVersion: string): Promise<void> {
113	  assertPhp(phpVersion);
114	  const svc = `php${phpVersion}-fpm`;
115	  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
116	  if (have.stdout.trim() === "yes") return;
117	  const prefix = await pkgInstallPrefix(conn);
118	  // php{ver}-fpm + the common extensions apps need.
119	  const inst = await exec(
120	    conn,
121	    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
122	    INSTALL_TIMEOUT_MS
123	  );
124	  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
125	  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
126	}
