199	export async function websiteSsl(job: Job): Promise<void> {
200	  const site = await loadSite(job);
201	  try {
202	    if (REAL) {
203	      assertDomain(site.domain);
204	      const server = await sshServer(site.serverId);
205	      const email = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
206	      await withServerSsh(server, async (conn) => {
207	        const have = await exec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
208	        if (have.stdout.trim() !== "yes") {
209	          const prefix = await pkgInstallPrefix(conn);
210	          const inst = await exec(conn, `${prefix} certbot python3-certbot-nginx`, INSTALL_TIMEOUT_MS);
211	          if (inst.code !== 0) throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
212	        }
213	        // Use the nginx installer so the vhost is upgraded to 443 in place.
214	        const run = await exec(
215	          conn,
216	          `certbot --nginx -n --agree-tos -m ${shellQuote(email)} -d ${shellQuote(site.domain)} --redirect`,
217	          INSTALL_TIMEOUT_MS
218	        );
219	        const combined = `${run.stdout}\n${run.stderr}`;
220	        const ok = run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i.test(combined);
221	        if (!ok) throw new Error(`certbot failed: ${combined.trim().slice(0, 300)}`);
222	      });
223	    }
224	    await db.website.update({ where: { id: site.id }, data: { ssl: true, error: null } });
225	    await notify(
226	      site.userId,
227	      `SSL enabled for ${site.domain}`,
228	      REAL ? "A Let's Encrypt certificate is installed and HTTP redirects to HTTPS." : "SSL enabled (sandbox).",
229	      `/dashboard/servers/${site.serverId}?tab=control panel`
230	    );
